#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumSize(vector<int>& nums, int maxOperations) {
        int low = 1, high = *max_element(nums.begin(), nums.end());
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long long ops = 0;
            for (int x : nums) {
                ops += (x - 1) / mid;
            }
            if (ops <= maxOperations) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumSize(int[] nums, int maxOperations) {
        int low = 1, high = 0;
        for (int x : nums) if (x > high) high = x;
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long ops = 0;
            for (int x : nums) {
                ops += (x - 1) / mid;
            }
            if (ops <= maxOperations) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} maxOperations
 * @return {number}
 */
var minimumSize = function(nums, maxOperations) {
    let low = 1, high = Math.max(...nums);
    let ans = high;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let ops = 0;
        for (const x of nums) {
            ops += Math.floor((x - 1) / mid);
        }
        if (ops <= maxOperations) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
